package fr.cake.client;
import java.util.*;
import java.util.zip.*;
import java.nio.file.*;
import java.awt.image.BufferedImage;
import net.minecraft.client.Minecraft;
public final class PvpCustomizer {
 private static final String PACK="file/Cake-PvP-Customizer.zip";private static boolean loading;private static long due;private static Object world;private static String status="Choisis un objet, inspecte-le puis applique le pack.";
 private static final String[][] FILES={{"entity/end_crystal/end_crystal.png"},{"item/mace.png"},{"item/totem_of_undying.png"},{"block/obsidian.png"},{"block/respawn_anchor_top.png","block/respawn_anchor_bottom.png","block/respawn_anchor_side0.png","block/respawn_anchor_side1.png","block/respawn_anchor_side2.png","block/respawn_anchor_side3.png","block/respawn_anchor_side4.png"}};
 private static final Map<String,BufferedImage> previews=new LinkedHashMap<>(16,.75f,true){@Override protected boolean removeEldestEntry(Map.Entry<String,BufferedImage> e){return size()>8;}};
 public static BufferedImage preview(int item,int variant,int angle){if(variant==0)return null;String key=variant+"-"+item+"-"+angle;if(previews.containsKey(key))return previews.get(key);BufferedImage image=null;for(int a:new int[]{angle,0})try(var in=PvpCustomizer.class.getResourceAsStream("/assets/cakeclient/pvp/previews/"+variant+"-"+item+"-"+a+".png")){if(in!=null){image=javax.imageio.ImageIO.read(in);break;}}catch(Exception ignored){}previews.put(key,image);return image;}
 public static boolean loading(){return loading;}
 public static String status(){return status;}public static String label(int index){return PvpCatalog.get(index).name();}
 public static void cycle(int item,int direction){var s=CakeClient.settings;s.pvpTextures[item]=PvpCatalog.next(item,s.pvpTextures[item],direction);s.changed();s.save();due=System.nanoTime()+650_000_000L;}
 public static void tick(){var mc=Minecraft.getInstance();if(mc.level==null){world=null;return;}if(world!=mc.getConnection()){world=mc.getConnection();if(java.util.Arrays.stream(CakeClient.settings.pvpTextures).anyMatch(x->x>0)||mc.getResourcePackRepository().getSelectedIds().stream().anyMatch(x->x.endsWith("Cake-PvP-Customizer.zip")))due=System.nanoTime()+1_000_000_000L;}if(due!=0&&System.nanoTime()>=due&&!loading&&!RealisticMode.loading()){due=0;apply();}}
 public static void apply(){if(loading)return;loading=true;var mc=Minecraft.getInstance();try{Path dir=net.fabricmc.loader.api.FabricLoader.getInstance().getGameDir().resolve("resourcepacks");Files.createDirectories(dir);Path temp=dir.resolve("Cake-PvP-Customizer.tmp");boolean enabled=false;Map<String,byte[]> entries=new LinkedHashMap<>();
  entries.put("pack.mcmeta","{\"pack\":{\"description\":\"Cake PvP Customizer · credits inside\",\"min_format\":[75,0],\"max_format\":[75,0],\"pack_format\":75}}".getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder credits=new StringBuilder("Cake PvP Customizer\nFaithful — https://faithfulpack.net/\nOriginal independent artist packs below; licenses included.\n");
  for(int item=0;item<5;item++){int v=CakeClient.settings.pvpTextures[item];if(v==0)continue;enabled=true;var choice=PvpCatalog.get(v);credits.append(choice.name()).append(" — ").append(choice.author()).append(" — ").append(choice.license()).append('\n').append(choice.source()).append('\n');String resource="/assets/cakeclient/pvp/"+v+(v<=8?"":"-"+item)+".zip";
   try(var in=PvpCustomizer.class.getResourceAsStream(resource)){if(in==null)throw new java.io.IOException("Pack absent : "+choice.name());try(var zip=new ZipInputStream(in)){ZipEntry e;while((e=zip.getNextEntry())!=null){String path=e.getName();if(e.isDirectory()||path.contains("..")||path.startsWith("/"))continue;boolean accept=v>8||!path.startsWith("assets/");if(v<=8)for(String file:FILES[item])if(path.equals("assets/minecraft/textures/"+file)||path.equals("assets/minecraft/textures/"+file+".mcmeta"))accept=true;if(accept)entries.put(path,zip.readAllBytes());}}}
  }
  entries.put("CREDITS.txt",credits.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));for(int i=1;i<=2;i++)try(var in=PvpCustomizer.class.getResourceAsStream("/assets/cakeclient/pvp/LICENSE-"+i+".txt")){if(in!=null)entries.put("LICENSE-Faithful-"+i+".txt",in.readAllBytes());}
  PvpOverrides.install(entries);
  try(var zip=new ZipOutputStream(Files.newOutputStream(temp))){for(var e:entries.entrySet()){zip.putNextEntry(new ZipEntry(e.getKey()));zip.write(e.getValue());zip.closeEntry();}}
  Files.move(temp,dir.resolve("Cake-PvP-Customizer.zip"),StandardCopyOption.REPLACE_EXISTING);var repo=mc.getResourcePackRepository();repo.reload();var selected=new ArrayList<>(repo.getSelectedIds());selected.removeIf(x->x.endsWith("Cake-PvP-Customizer.zip"));String actual=repo.getAvailableIds().stream().filter(x->x.endsWith("Cake-PvP-Customizer.zip")).findFirst().orElse(PACK);if(enabled){if(!repo.getAvailableIds().contains(actual))throw new java.io.IOException("Le pack généré est refusé par Minecraft");selected.add(actual);}repo.setSelected(selected);if(enabled&&!repo.getSelectedIds().contains(actual))throw new java.io.IOException("Le pack généré n’est pas sélectionné");mc.options.resourcePacks.clear();for(var pack:repo.getSelectedPacks())if(!pack.isFixedPosition())mc.options.resourcePacks.add(pack.getId());mc.options.incompatibleResourcePacks.removeIf(x->x.endsWith("Cake-PvP-Customizer.zip"));mc.options.save();status="Chargement des textures…";mc.reloadResourcePacks().whenComplete((v,error)->mc.execute(()->{loading=false;status=error==null?"Textures et modèles appliqués":"Chargement impossible · voir latest.log";CakeClient.settings.changed();}));
 }catch(Exception e){loading=false;status="Pack indisponible · voir latest.log";CakeClient.LOG.warn("PvP customizer failed",e);}}
}
